mapper.select:
/*selectMasterMdCmCmsItemAltCodeSelPopList*/ SELECT CMS_CATLG_ID /* 상품정보코드 */ ,DECODE(STATUS, 'D', '미사용', '사용') AS STATUS_NM /* 상품상태 */ ,STATUS /* 상품상태(원값) */ ,DESCRIPTION_LOC /* 품목명 */ ,MODEL_INFO /* 모델번호 */ ,SPECIFICATION /* 규격 */ ,MAKER_NAME /* 제조사 */ ,(SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M001' AND CODE = ORIGIN_CODE) AS ORIGIN_CODE_NAME /* 원산지 */ ,ORDER_MEASURE /* 단위 */ ,NVL(ONETIME_YN,'N') AS ONETIME_YN /* 일회성구분(원값 Y/N) */ ,DECODE(NVL(ONETIME_YN,'N'), 'Y', '일회성', '일반') AS ONETIME_NM /* 일회성구분 */ FROM CMSCATLG WHERE 1=1
AND CMS_CATLG_ID IN
UPPER(#{item})
AND CMS_CATLG_ID = UPPER(#{st_cmscatlg})
AND DESCRIPTION_LOC LIKE '%' || #{st_item_name} || '%'
AND MODEL_INFO LIKE '%' || #{st_model_info} || '%'
AND SPECIFICATION LIKE '%' || #{st_specification} || '%'
AND MAKER_CODE = #{st_maker_code}
AND ORDER_MEASURE = #{st_order_measure}
AND EXISTS (SELECT 1 FROM CMSCATEG CG WHERE CG.CMS_CATEG_ID = CMSCATLG.CMS_CATEG_ID AND CG.STATUS != 'D' AND CG.SG_ID IN
#{item}
)
AND CMS_CATEG_ID IN
#{item}
ORDER BY CMS_CATLG_ID
